29: /// Core flight telemetry exporter trait for writing directly to any standard `io::Write` sink.
30: pub trait FlightExporter {
31:     /// Serializes the dataset directly to the provided writer.
32:     fn export<W: Write>(&self, dataset: &FlightDataset, writer: &mut W) -> Result<(), ExportError>;
33: }
34: 
35: /// Ergonomic extension methods automatically provided for all `FlightExporter` types.
36: pub trait FlightExporterExt: FlightExporter {
37:     /// Export the dataset directly to a file on disk with buffered I/O.
38:     fn export_to_file<P: AsRef<Path>>(&self, dataset: &FlightDataset, path: P) -> Result<(), ExportError> {
39:         let file = std::fs::File::create(path)?;
40:         let mut writer = std::io::BufWriter::new(file);
41:         self.export(dataset, &mut writer)?;
42:         writer.flush()?;
43:         Ok(())
44:     }
45: 
46:     /// Export the dataset into an allocated memory buffer (`Vec<u8>`).
47:     fn export_to_vec(&self, dataset: &FlightDataset) -> Result<Vec<u8>, ExportError> {
48:         let mut buf = Vec::new();
49:         self.export(dataset, &mut buf)?;
50:         Ok(buf)
51:     }
52: 
53:     /// Export the dataset into a UTF-8 string.
54:     fn export_to_string(&self, dataset: &FlightDataset) -> Result<String, ExportError> {
55:         let bytes = self.export_to_vec(dataset)?;
56:         String::from_utf8(bytes).map_err(|e| ExportError::Formatting(e.to_string()))
57:     }
58: }
59: 
60: impl<T: FlightExporter + ?Sized> FlightExporterExt for T {}
61: 
62: /// Enumeration of all supported export file formats.
63: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
64: pub enum ExportFormat {
65:     /// RFC 4180 Comma-Separated Values.
66:     Csv,
67:     /// Open Geospatial Consortium KML 2.2 3D aerial model.
68:     Kml,
69:     /// TopoGrafix GPX 1.1 GPS Exchange format.
70:     Gpx,
71:     /// RFC 7946 GeoJSON FeatureCollection.
72:     GeoJson,
73:     /// Hierarchical Flight Summary JSON.
74:     Json,
75: }
76: 
77: impl ExportFormat {
78:     /// Returns the standard canonical file extension without leading dot.
79:     pub const fn file_extension(&self) -> &'static str {
80:         match self {
81:             Self::Csv => "csv",
82:             Self::Kml => "kml",
83:             Self::Gpx => "gpx",
84:             Self::GeoJson => "geojson",
85:             Self::Json => "json",
86:         }
87:     }
88: 
89:     /// Returns the standard IANA MIME media type.
90:     pub const fn mime_type(&self) -> &'static str {
91:         match self {
92:             Self::Csv => "text/csv; charset=utf-8",
93:             Self::Kml => "application/vnd.google-earth.kml+xml",
94:             Self::Gpx => "application/gpx+xml",
95:             Self::GeoJson => "application/geo+json",
96:             Self::Json => "application/json",
97:         }
98:     }
99: }
100: 
101: impl std::str::FromStr for ExportFormat {
102:     type Err = ExportError;
103: 
104:     fn from_str(s: &str) -> Result<Self, Self::Err> {
105:         match s.to_ascii_lowercase().as_str() {
106:             "csv" => Ok(Self::Csv),
107:             "kml" => Ok(Self::Kml),
108:             "gpx" => Ok(Self::Gpx),
109:             "geojson" => Ok(Self::GeoJson),
110:             "json" | "summary" => Ok(Self::Json),
111:             other => Err(ExportError::UnsupportedFormat(format!(
112:                 "Unsupported export format '{other}'. Supported formats: csv, kml, gpx, geojson, json"
113:             ))),
114:         }
115:     }
116: }
117: 
118: /// Unified dispatcher function exporting a dataset into the target format.
119: pub fn export_dataset<W: Write>(
120:     dataset: &FlightDataset,
121:     format: ExportFormat,
122:     writer: &mut W,
123: ) -> Result<(), ExportError> {
124:     match format {
125:         ExportFormat::Csv => CsvExporter::default().export(dataset, writer),
126:         ExportFormat::Kml => KmlExporter::default().export(dataset, writer),
127:         ExportFormat::Gpx => GpxExporter::default().export(dataset, writer),
128:         ExportFormat::GeoJson => GeoJsonExporter::default().export(dataset, writer),
129:         ExportFormat::Json => JsonSummaryExporter::default().export(dataset, writer),
130:     }
131: }
132: 
133: /// Unified helper function exporting a dataset directly to a file path.
134: pub fn export_to_file<P: AsRef<Path>>(
135:     dataset: &FlightDataset,
136:     format: ExportFormat,
137:     path: P,
138: ) -> Result<(), ExportError> {
139:     let file = std::fs::File::create(path)?;
140:     let mut writer = std::io::BufWriter::new(file);
141:     export_dataset(dataset, format, &mut writer)?;
142:     writer.flush()?;
143:     Ok(())
144: }
