55:     /// Converts Web RGB hex color `#RRGGBB` and opacity percentage (0..=100) to KML `AABBGGRR`.
56:     pub fn to_kml_abgr(hex_rgb: &str, opacity_pct: u8) -> String {
57:         let clean = hex_rgb.trim_start_matches('#');
58:         if clean.len() != 6 {
59:             return "ffffffff".to_string();
60:         }
61:         let r = &clean[0..2];
62:         let g = &clean[2..4];
63:         let b = &clean[4..6];
64:         let alpha = ((opacity_pct as f64 / 100.0) * 255.0).round() as u8;
65:         format!("{:02x}{}{}{}", alpha, b, g, r)
66:     }
67: 
68:     fn filter_jitter<'a>(&self, points: &'a [TelemetryPoint]) -> Vec<&'a TelemetryPoint> {
69:         if points.is_empty() {
70:             return Vec::new();
71:         }
72:         let threshold = match self.options.jitter_filter_m {
73:             Some(t) if t > 0.0 => t,
74:             _ => return points.iter().collect(),
75:         };
76: 
77:         let mut out = Vec::with_capacity(points.len());
78:         out.push(&points[0]);
79: 
80:         for pt in &points[1..points.len() - 1] {
81:             let prev = out.last().unwrap();
82:             let d_lat = (pt.latitude - prev.latitude).abs() * 111_000.0;
83:             let d_lon = (pt.longitude - prev.longitude).abs() * 111_000.0 * pt.latitude.to_radians().cos().abs();
84:             let d_alt = (pt.altitude_msl - prev.altitude_msl).abs();
85:             let dist_3d = (d_lat * d_lat + d_lon * d_lon + d_alt * d_alt).sqrt();
86: 
87:             if dist_3d >= threshold {
88:                 out.push(pt);
89:             }
90:         }
91: 
92:         if points.len() > 1 {
93:             out.push(points.last().unwrap());
94:         }
95: 
96:         out
97:     }
98: }
