//! Adversarial empirical test and export dumper for Challenger M1-2.

use std::fs;
use std::path::Path;

use flightreader_export::exporters::{
    CsvDialect, CsvExporter, CsvOptions, ExportFormat, FlightExporterExt, GeoJsonExporter,
    GeoJsonOptions, GpxExporter, GpxOptions, JsonSummaryExporter, JsonSummaryOptions, KmlExporter,
    KmlOptions, LineEnding,
};
use flightreader_export::model::{
    FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
};

fn make_point(
    idx: usize,
    lat: f64,
    lon: f64,
    alt_msl: f64,
    alt_agl: f64,
    spd: f64,
    yaw: f64,
    cells: Vec<u16>,
    is_motor: bool,
    warning: Option<&str>,
) -> TelemetryPoint {
    let ts_ms = 1_729_000_000_000i64 + (idx as i64 * 100);
    let iso = chrono::DateTime::from_timestamp_millis(ts_ms)
        .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
        .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string());

    let (c_dev, pack_mv) = if cells.is_empty() {
        (0, 0)
    } else {
        let min_c = *cells.iter().min().unwrap();
        let max_c = *cells.iter().max().unwrap();
        let sum_mv: u32 = cells.iter().map(|&c| c as u32).sum();
        (max_c - min_c, sum_mv)
    };

    TelemetryPoint {
        index: idx,
        timestamp_utc_ms: ts_ms,
        timestamp_iso8601: iso,
        elapsed_s: idx as f64 * 0.1,
        fly_time_s: if idx < 10 { 0.0 } else { (idx - 10) as f64 * 0.1 },
        latitude: lat,
        longitude: lon,
        altitude_msl: alt_msl,
        altitude_agl: alt_agl,
        altitude_baro: alt_agl,
        vps_height_m: if alt_agl < 3.0 { Some(alt_agl) } else { None },
        ground_speed_mps: spd,
        speed_3d_mps: spd,
        climb_rate_mps: 0.0,
        vel_n: spd,
        vel_e: 0.0,
        vel_d: 0.0,
        course_deg: yaw,
        pitch_deg: -5.0,
        roll_deg: 0.0,
        yaw_deg: yaw,
        heading_deg: yaw,
        gimbal_pitch_deg: -30.0,
        gimbal_roll_deg: 0.0,
        gimbal_yaw_deg: 0.0,
        gimbal_mode: "Follow".to_string(),
        rc_aileron: 0.0,
        rc_elevator: 0.2,
        rc_throttle: 0.5,
        rc_rudder: 0.0,
        rc_mode_switch: "P".to_string(),
        rc_signal_quality: 100,
        battery_pct: 90,
        battery_voltage_mv: pack_mv,
        battery_temp_c: 26.5,
        battery_current_a: Some(7.5),
        cell_voltages_mv: cells,
        cell_deviation_mv: c_dev,
        gps_satellites: 16,
        gps_level: 5,
        flight_mode: "P-GPS".to_string(),
        ground_state: if is_motor { "Airborne".to_string() } else { "OnGround".to_string() },
        is_motor_on: is_motor,
        is_failsafe_active: false,
        app_warning: warning.map(|s| s.to_string()),
        app_tip: None,
    }
}

/// Dumps all exported datasets to /tmp/test_exports_m1_2/ for oracle verification.
#[test]
fn dump_datasets_for_oracle_verification() {
    let export_dir = Path::new("/tmp/test_exports_m1_2");
    if export_dir.exists() {
        fs::remove_dir_all(export_dir).unwrap();
    }
    fs::create_dir_all(export_dir).unwrap();

    // 1. Canonical Cruise Dataset (100 points)
    let mut ds_cruise = FlightDataset::default();
    ds_cruise.metadata.aircraft_model = Some("DJI Mavic 3 Pro".to_string());
    ds_cruise.metadata.home_latitude = Some(47.606212);
    ds_cruise.metadata.home_longitude = Some(-122.332145);
    ds_cruise.metadata.home_altitude_msl = Some(120.0);
    for i in 0..100 {
        ds_cruise.points.push(make_point(
            i,
            47.606212 + i as f64 * 0.0001,
            -122.332145 + i as f64 * 0.0001,
            120.0 + (i as f64 * 0.5),
            i as f64 * 0.5,
            12.5,
            45.0,
            vec![3850, 3848, 3852, 3849],
            true,
            None,
        ));
    }
    ds_cruise.events.push(FlightEvent {
        timestamp_utc_ms: 1_729_000_000_000,
        elapsed_s: 0.0,
        flight_time_s: 0.0,
        event_type: FlightEventType::Takeoff,
        description: "Motors armed and departed surface".to_string(),
        message: "Takeoff".to_string(),
        latitude: Some(47.606212),
        longitude: Some(-122.332145),
        altitude_msl: Some(120.0),
    });

    // 2. Single-point Trajectory Dataset (1 point, negative altitude, missing cells)
    let mut ds_single = FlightDataset::default();
    ds_single.metadata.aircraft_model = Some("DJI Mini 4".to_string());
    ds_single.metadata.home_latitude = Some(36.2415);
    ds_single.metadata.home_longitude = Some(-116.8258);
    ds_single.metadata.home_altitude_msl = Some(-86.0);
    ds_single.points.push(make_point(
        0,
        36.2415,
        -116.8258,
        -86.0, // Death Valley negative elevation
        5.0,
        0.0,   // zero ground speed
        0.0,
        vec![], // zero battery cells
        false,
        None,
    ));

    // 3. Multi-Segment & Warning / RTH Dataset
    let mut ds_multi = FlightDataset::default();
    ds_multi.metadata.home_latitude = Some(47.606212);
    ds_multi.metadata.home_longitude = Some(-122.332145);
    ds_multi.metadata.home_altitude_msl = Some(120.0);
    for i in 0..50 {
        let (warn, fail, soc) = if i < 20 {
            (None, false, 80)
        } else if i < 35 {
            (Some("High Wind Velocity. Caution!"), false, 50)
        } else {
            (Some("Low Battery Critical RTH"), true, 18)
        };
        let mut pt = make_point(
            i,
            47.606212 + i as f64 * 0.0001,
            -122.332145 + i as f64 * 0.0001,
            120.0 + (i as f64 * 0.2),
            15.0,
            8.0,
            90.0,
            vec![3750, 3740, 3760, 3745],
            true,
            warn,
        );
        pt.is_failsafe_active = fail;
        pt.battery_pct = soc;
        ds_multi.points.push(pt);
    }
    ds_multi.events.push(FlightEvent {
        timestamp_utc_ms: 1_729_000_003_500,
        elapsed_s: 3.5,
        flight_time_s: 3.5,
        event_type: FlightEventType::RthTriggered,
        description: "Low Battery Return to Home".to_string(),
        message: "RTH Triggered".to_string(),
        latitude: Some(47.6097),
        longitude: Some(-122.3286),
        altitude_msl: Some(127.0),
    });

    // 4. Special Characters & Quotes Dataset
    let mut ds_special = FlightDataset::default();
    ds_special.metadata.aircraft_model = Some("<Special & Drone \"X\" 'Pro'>".to_string());
    ds_special.metadata.aircraft_name = Some("DJI 航模 / 飛行記録 🚁 (100% 正常)".to_string());
    ds_special.points.push(make_point(
        0,
        47.606212,
        -122.332145,
        100.0,
        10.0,
        5.0,
        180.0,
        vec![3800, 3810],
        true,
        Some("Caution: \"\"obstacle\"\" ahead, <abort> & return!"),
    ));
    ds_special.points.push(make_point(
        1,
        47.606312,
        -122.332045,
        102.0,
        12.0,
        6.0,
        185.0,
        vec![3790, 3800],
        true,
        Some("Line 1\r\nLine 2, with \"quotes\" and commas"),
    ));

    // 5. Empty Dataset (0 points)
    let ds_empty = FlightDataset::default();

    // Helper macro to dump a dataset in all formats
    let dump_all = |name: &str, ds: &FlightDataset| {
        // CSV Standard
        let csv_path = export_dir.join(format!("{name}_standard.csv"));
        CsvExporter::new(CsvOptions {
            dialect: CsvDialect::Standard,
            include_bom: false,
            line_ending: LineEnding::Crlf,
        })
        .export_to_file(ds, &csv_path)
        .unwrap();

        // CSV Overlay
        let overlay_path = export_dir.join(format!("{name}_overlay.csv"));
        CsvExporter::new(CsvOptions {
            dialect: CsvDialect::TelemetryOverlay,
            include_bom: false,
            line_ending: LineEnding::Crlf,
        })
        .export_to_file(ds, &overlay_path)
        .unwrap();

        // KML
        let kml_path = export_dir.join(format!("{name}.kml"));
        KmlExporter::default().export_to_file(ds, &kml_path).unwrap();

        // GPX
        let gpx_path = export_dir.join(format!("{name}.gpx"));
        GpxExporter::default().export_to_file(ds, &gpx_path).unwrap();

        // GeoJSON
        let geojson_path = export_dir.join(format!("{name}.geojson"));
        GeoJsonExporter::new(GeoJsonOptions {
            include_coordinate_properties: true,
            pretty: true,
        })
        .export_to_file(ds, &geojson_path)
        .unwrap();

        // JSON Summary
        let json_path = export_dir.join(format!("{name}_summary.json"));
        JsonSummaryExporter::new(JsonSummaryOptions { pretty: true })
            .export_to_file(ds, &json_path)
            .unwrap();
    };

    dump_all("cruise", &ds_cruise);
    dump_all("single", &ds_single);
    dump_all("multi", &ds_multi);
    dump_all("special", &ds_special);
    dump_all("empty", &ds_empty);

    println!("All test datasets dumped to {:?}", export_dir);
}

